changeSet.sql:
CREATE TABLE activity_chat_messages (
      id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      activite_id bigint NOT NULL REFERENCES activites(id) ON DELETE CASCADE,
      sender_user_id bigint NOT NULL,
      sender_name varchar(255) NOT NULL,
      content varchar(2000) NOT NULL,
      created_at timestamp with time zone NOT NULL,
      CONSTRAINT ck_activity_chat_content CHECK (char_length(trim(content)) > 0)
    );
    CREATE INDEX idx_activity_chat_activity_id ON activity_chat_messages (activite_id, id);
